cypress_script:
describe('Tool Tips Functionality', () => {
  it('should display tooltip on input field hover', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.get('#toolTipTextField').trigger('mouseover');
    cy.get('#toolTipTextField').should('be.visible');
  });
  it('should not change URL on hover', () => {
    cy.visit('https://demoqa.com/tool-tips');
    cy.url().should('eq', 'https://demoqa.com/tool-tips');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Tips Functionality', () => {
  test('should display tooltip on input field hover', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    const tooltipField = page.locator('#toolTipTextField');
    await tooltipField.hover();
    await expect(tooltipField).toBeVisible();
  });
  test('should not change URL on hover', async ({ page }) => {
    await page.goto('https://demoqa.com/tool-tips');
    await page.locator('#toolTipTextField').hover();
    await expect(page).toHaveURL('https://demoqa.com/tool-tips');
  });
});
